parameters.jsCode:
// Generate invoice HTML from transaction data
const transaction = $('Transaction Transitioned').first().json;
const resource = transaction.resource;

const transactionId = transaction.resourceId;
const date = new Date(transaction.createdAt).toLocaleDateString('en-US', {
  year: 'numeric', month: 'long', day: 'numeric'
});

// Extract pricing (update field paths based on your transaction data)
const amount = resource.payinTotal?.amount || 0;
const currency = resource.payinTotal?.currency || 'USD';
const formattedAmount = (amount / 100).toFixed(2);

const invoiceHtml = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto; padding: 40px; }
    .header { display: flex; justify-content: space-between; margin-bottom: 40px; }
    .invoice-title { font-size: 28px; font-weight: bold; color: #333; }
    .details { margin-bottom: 30px; }
    .details p { margin: 4px 0; color: #555; }
    table { width: 100%; border-collapse: collapse; margin: 20px 0; }
    th { background: #f5f5f5; text-align: left; padding: 12px; border-bottom: 2px solid #ddd; }
    td { padding: 12px; border-bottom: 1px solid #eee; }
    .total-row td { font-weight: bold; font-size: 18px; border-top: 2px solid #333; }
    .footer { margin-top: 40px; padding-top: 20px; border-top: 1px solid #eee; color: #888; font-size: 12px; }
  </style>
</head>
<body>
  <div class="header">
    <div>
      <div class="invoice-title">INVOICE</div>
      <p style="color: #888;">Your Marketplace Name</p>
    </div>
    <div style="text-align: right;">
      <p><strong>Invoice #:</strong> INV-${transactionId.substring(0, 8).toUpperCase()}</p>
      <p><strong>Date:</strong> ${date}</p>
      <p><strong>Transaction:</strong> ${transactionId}</p>
    </div>
  </div>

  <div class="details">
    <p><strong>Bill To:</strong></p>
    <p>Customer Name (update with Get User data)</p>
    <p>customer@example.com</p>
  </div>

  <table>
    <thead>
      <tr>
        <th>Description</th>
        <th style="text-align: right;">Amount</th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td>Marketplace Transaction</td>
        <td style="text-align: right;">${currency} ${formattedAmount}</td>
      </tr>
      <tr class="total-row">
        <td>Total</td>
        <td style="text-align: right;">${currency} ${formattedAmount}</td>
      </tr>
    </tbody>
  </table>

  <div class="footer">
    <p>Thank you for your business!</p>
    <p>Your Marketplace Name | your-marketplace.com</p>
  </div>
</body>
</html>
`;

return [{ json: { invoiceHtml, transactionId, date, amount: formattedAmount, currency } }];

